import sqlite3
import csv

# Read frpm.csv
frpm_data = []
with open('csv/frpm.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        frpm_data.append(row)

# Get unique Riverside-related districts
riverside_districts = set()
for row in frpm_data:
    if 'Riverside' in row['District Name']:
        riverside_districts.add(row['District Name'])

print("Riverside-related districts:", riverside_districts)

# Connect to satscores.db
conn = sqlite3.connect('db/satscores.db')
cursor = conn.cursor()

# Build a dict of cds -> avg math score
cds_math_scores = {}
cursor.execute("SELECT cds, AvgScrMath FROM satscores WHERE AvgScrMath IS NOT NULL")
for row in cursor.fetchall():
    cds, math_score = row
    if cds not in cds_math_scores:
        cds_math_scores[cds] = []
    cds_math_scores[cds].append(math_score)

# Calculate average math score per district (using frpm data joined with satscores)
district_avg_math = {}
for row in frpm_data:
    cds = row['CDSCode']
    district = row['District Name']
    if district in riverside_districts and cds in cds_math_scores:
        if district not in district_avg_math:
            district_avg_math[district] = []
        district_avg_math[district].extend(cds_math_scores[cds])

# Calculate district averages
district_averages = {}
for district, scores in district_avg_math.items():
    if scores:
        district_averages[district] = sum(scores) / len(scores)

print("\nDistrict averages:")
for d, avg in district_averages.items():
    print(f"  {d}: {avg:.2f}")

# Filter districts with average > 400
qualifying_districts = {d for d, avg in district_averages.items() if avg > 400}
print("\nQualifying districts (avg > 400):", qualifying_districts)

# Get schools from qualifying districts
result = []
for row in frpm_data:
    if row['District Name'] in qualifying_districts:
        result.append({
            'School Name': row['School Name'],
            'Funding Type': row['Charter Funding Type']
        })

print(f"\nTotal schools in qualifying districts: {len(result)}")
print("First 10 results:")
for r in result[:10]:
    print(r)

